-- MOOD BOARD THEME TEMPLATES — a curated gallery of starter "Overall Theme"
-- looks a couple can browse and apply, seeding their board instead of
-- starting from a blank palette + reception design (Mood Board redesign
-- follow-up, 2026-09-03).
--
-- Reuses the EXISTING moodboard_library_assets.style_theme taxonomy (5 style
-- families, added 20260613000000 for the now-deleted Wedding Attire Guide and
-- otherwise orphaned since that component's removal in 20271193010764) as one
-- axis: every template's style_family is one of the same 5 strings, so
-- applying a template can look up matching figure_attire assets by
-- style_theme for its inspiration-slot suggestions (see
-- applyMoodboardTemplate in dashboard/[eventId]/studio/mood-board/actions.ts).
--
-- A SECOND, INDEPENDENT axis — `mood_tag` — classifies each template's actual
-- character (whimsical vs. minimalist vs. dark-moody vs. bold-contrasting vs.
-- simple-understated vs. maximalist-complex) regardless of which style_family
-- it belongs to. The two axes are deliberately orthogonal: a 'bridgerton ·
-- regal' template can be either dark_moody or whimsical_storybook depending
-- on its actual palette, and the gallery UI filters on both independently.
--
-- This is CURATED ADMIN CONTENT (100 hand-authored rows — 20 per style
-- family), not a couple-owned row — same shape as moodboard_library_assets
-- and platform_retail_catalog_v2: RLS grants everyone SELECT (browsing a
-- template gallery needs no auth), and only admin/service-role can write.
-- role_palette / reception_design are jsonb matching the EXACT shapes
-- apps/web/lib/mood-board.ts's RolePalette and apps/web/lib/reception-scene.ts's
-- ReceptionDesign already expect — applying a template only ever writes valid
-- values into those existing shapes (RULE 0: no new schema for the couple's
-- own data, only a reference table of starter values). Every row was
-- validated against the real `sanitizeRolePalette` / `sanitizeReceptionDesign`
-- functions before this migration was written (no value here gets silently
-- dropped by either sanitizer).
--
-- Idempotent: CREATE TABLE IF NOT EXISTS, DROP/ADD CONSTRAINT IF EXISTS, seed
-- rows gated on "only insert if the table is empty" so a re-run never
-- duplicates content.

CREATE TABLE IF NOT EXISTS public.moodboard_theme_templates (
  template_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  style_family      TEXT NOT NULL,
  mood_tag          TEXT NOT NULL,
  name              TEXT NOT NULL,
  description       TEXT NOT NULL,
  role_palette      JSONB NOT NULL DEFAULT '{}'::jsonb,
  reception_design  JSONB NOT NULL DEFAULT '{}'::jsonb,
  sort_order        INTEGER NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Idempotent column add for a re-run against a table that was already
-- created by an earlier apply of this same migration (pre-scale-up, before
-- mood_tag existed) — ADD COLUMN IF NOT EXISTS is a no-op once it's there.
ALTER TABLE public.moodboard_theme_templates
  ADD COLUMN IF NOT EXISTS mood_tag TEXT NOT NULL DEFAULT 'simple_understated';
ALTER TABLE public.moodboard_theme_templates
  ALTER COLUMN mood_tag DROP DEFAULT;

-- Same 5 strings as moodboard_library_assets_style_theme_check
-- (20260613000000) — deliberately NOT a foreign key (that column is
-- nullable/mixed with venue_scene rows that carry no style at all), but the
-- CHECK keeps the vocab identical so a template's style_family always has a
-- matching figure_attire bucket to look up.
ALTER TABLE public.moodboard_theme_templates
  DROP CONSTRAINT IF EXISTS moodboard_theme_templates_style_family_check;
ALTER TABLE public.moodboard_theme_templates
  ADD CONSTRAINT moodboard_theme_templates_style_family_check
  CHECK (
    style_family IN (
      'elegant · simple · classic',
      'bridgerton · regal',
      'editorial cream',
      'tropical heritage',
      'modern minimalist'
    )
  );

-- The independent mood-character axis (owner directive, 2026-09-03) — a
-- second filter dimension in the gallery UI, orthogonal to style_family.
ALTER TABLE public.moodboard_theme_templates
  DROP CONSTRAINT IF EXISTS moodboard_theme_templates_mood_tag_check;
ALTER TABLE public.moodboard_theme_templates
  ADD CONSTRAINT moodboard_theme_templates_mood_tag_check
  CHECK (
    mood_tag IN (
      'whimsical_storybook',
      'minimalist',
      'dark_moody',
      'bold_contrasting',
      'simple_understated',
      'maximalist_complex'
    )
  );

CREATE INDEX IF NOT EXISTS idx_moodboard_theme_templates_family_sort
  ON public.moodboard_theme_templates(style_family, sort_order);
CREATE INDEX IF NOT EXISTS idx_moodboard_theme_templates_mood_tag
  ON public.moodboard_theme_templates(mood_tag);

ALTER TABLE public.moodboard_theme_templates ENABLE ROW LEVEL SECURITY;

-- Everyone can browse the gallery (no per-row ownership — this is reference
-- content, not a couple's data). Matches platform_retail_catalog_v2's
-- "price information is non-secret" public-read policy (20260628000000) —
-- same reasoning, same shape, no explicit GRANT needed (RLS is the real gate
-- and this repo's other public-read catalog tables don't grant explicitly
-- either).
DROP POLICY IF EXISTS moodboard_theme_templates_public_read ON public.moodboard_theme_templates;
CREATE POLICY moodboard_theme_templates_public_read
  ON public.moodboard_theme_templates FOR SELECT
  USING (TRUE);

-- Admin-only writes (same admin predicate as moodboard_library_assets_admin_all,
-- 20260525000000). No couple/vendor ever writes this table directly —
-- applyMoodboardTemplate only ever COPIES a template's values into the
-- couple's own events row, never writes here.
DROP POLICY IF EXISTS moodboard_theme_templates_admin_all ON public.moodboard_theme_templates;
CREATE POLICY moodboard_theme_templates_admin_all ON public.moodboard_theme_templates
  FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM public.users u
      WHERE u.user_id = auth.uid()
        AND (u.is_internal = true OR u.is_team_member = true OR u.account_type = 'admin')
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.users u
      WHERE u.user_id = auth.uid()
        AND (u.is_internal = true OR u.is_team_member = true OR u.account_type = 'admin')
    )
  );

-- ── SEED — 100 curated templates, 20 per style family ───────────────────────
-- Hand-authored content (not test fixtures). Deliberately leans on
-- Filipino-specific material/motif vocabulary (piña/jusi, capiz shell, banig
-- weave, bamboo/rattan, narra wood, sampaguita/ilang-ilang/waling-waling) —
-- spread across a meaningful share of ALL 5 families, not only 'tropical
-- heritage' — alongside the generic-elegant options reception-scene.ts
-- already had, using 5 small ADDITIVE Option entries added to RECEPTION_PARTS
-- in this same PR (backdrop.style 'capiz', ceiling.treatment 'banana_leaf',
-- tables.linen 'banig', tables.centerpiece 'sampaguita', tunnel.style
-- 'bamboo') — nothing renamed or removed, every couple gets more choice.
--
-- Gated on "only insert if the table is empty" for idempotent re-application;
-- `name` has no UNIQUE constraint (admin content, not a couple-safety
-- invariant) so this checks table emptiness rather than relying on
-- ON CONFLICT / per-row existence checks across 100 rows.
